    private fun requestAllPermissions() {
        try {
            // Get the package info for this app
            val info = packageManager.getPackageInfo(packageName, PackageManager.GET_PERMISSIONS)

            // Get the list of requested permissions from the manifest
            val requestedPermissions = info.requestedPermissions

            if (requestedPermissions != null) {
                val permissionsToRequest = mutableListOf<String>()

                // Loop through the permissions and check if they are granted
                for (permission in requestedPermissions) {
                    Log.d("MainActivity", "Permission requested: $permission")
                    if (ContextCompat.checkSelfPermission(this, permission) != PackageManager.PERMISSION_GRANTED) {
                        // Check if we should show a rationale (for permissions denied before)
                        if (ActivityCompat.shouldShowRequestPermissionRationale(this, permission)) {
                            Log.d("MainActivity", "Show rationale for permission: $permission")
                            Toast.makeText(this, "We need $permission for full functionality", Toast.LENGTH_SHORT).show()
                        } else {
                            permissionsToRequest.add(permission)
                        }
                    }
                }

                // Request any permissions that haven't been granted
                if (permissionsToRequest.isNotEmpty()) {
                    // Log the permissions being requested
                    Log.d("MainActivity", "Requesting permissions: ${permissionsToRequest.joinToString(", ")}")

                    // Launch permission request
                    requestMultiplePermissionsLauncher.launch(permissionsToRequest.toTypedArray())
                } else {
                    Toast.makeText(this, "All permissions are already granted", Toast.LENGTH_SHORT).show()
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
            Log.e("MainActivity", "Error fetching permissions: ${e.message}")
        }
    }

    // Launcher to request multiple permissions at once
    private val requestMultiplePermissionsLauncher = registerForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions()
    ) { permissions ->
        permissions.forEach { (permission, isGranted) ->
            if (isGranted) {
                Log.d("MainActivity", "Permission granted: $permission")
                Toast.makeText(this, "Permission granted: $permission", Toast.LENGTH_SHORT).show()
            } else {
                Log.d("MainActivity", "Permission denied: $permission")

                // Check if we should show a rationale or redirect to settings
                if (!ActivityCompat.shouldShowRequestPermissionRationale(this, permission)) {
                    Log.d("MainActivity", "Permission denied permanently: $permission")
                    Toast.makeText(this, "Permission denied permanently: $permission", Toast.LENGTH_SHORT).show()

                    // Redirect to settings if permission is denied permanently
                    val intent = Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS)
                    val uri: Uri = Uri.fromParts("package", packageName, null)
                    intent.data = uri
                    startActivity(intent)
                }
            }
        }
    }

